    namespace = dict(vars(builtin))
    exec(compile(source.replace(union, replacement), "<builtin-read-scope-fault>", "exec"), namespace)
    builtin.PullRequestProvider = namespace["PullRequestProvider"]

def core_change(name, old, replacement):
